import json, re, os
from orca_task_sdk import run_orca

inp = '''! B3LYP def2-SVP RKS Opt Freq NoAutoStart
%maxcore 192
%scf
  MaxIter 256
  AutoTRAH false
end
%geom
  MaxIter 128
end
* xyzfile 0 1 coords.xyz
'''
with open('job.inp','w') as f:
    f.write(inp)
request_key='ethanol_opt_freq_v1'
error=None
try:
    res=run_orca('job.inp', dependencies=('coords.xyz',), request_key=request_key, purpose='new_candidate')
except Exception as e:
    error=str(e)
    res={'request_key':request_key,'operation_status':'error','files':{},'error':error}
files=res.get('files') or {}
def read_file(k):
    p=files.get(k)
    if not p:
        return ''
    try:
        with open(p, 'r', errors='replace') as f:
            return f.read()
    except Exception:
        return ''
jobxyz=read_file('job.xyz')
stdout=read_file('stdout.out')
geom=[]
lines=jobxyz.splitlines()
if len(lines)>=2:
    try:
        n=int(lines[0].strip())
        for line in lines[2:2+n]:
            parts=line.split()
            if len(parts)>=4:
                geom.append({'symbol':parts[0],'x':float(parts[1]),'y':float(parts[2]),'z':float(parts[3])})
    except Exception:
        geom=[]
freq=[]
for line in stdout.splitlines():
    m=re.match(r'^\s*(\d+):\s+(-?\d+(?:\.\d+)?)\s+cm\*\*-1', line)
    if m:
        freq.append({'mode':int(m.group(1)),'wavenumber_cm-1':float(m.group(2))})
conv=bool(re.search(r'THE OPTIMIZATION HAS CONVERGED|HURRAY.*CONVERGED|OPTIMIZATION RUN DONE', stdout, re.I))
if len(freq)>=27:
    vib=sorted(freq, key=lambda x: abs(x['wavenumber_cm-1']))[6:]
else:
    vib=sorted(freq, key=lambda x: abs(x['wavenumber_cm-1']))
imag=[x for x in vib if x['wavenumber_cm-1'] < -10.0]
if error:
    lm='SDK ORCA request failed; no scientific local-minimum assessment is possible.'
elif not conv:
    lm='Optimization convergence marker was not found in stdout; a local-minimum conclusion is not supported.'
elif not freq:
    lm='No frequency lines were parsed from stdout; a local-minimum conclusion is not supported.'
elif imag:
    lm='At least one parsed mode below -10 cm^-1 remains after excluding the six lowest modes; this does not support a local minimum in the harmonic approximation.'
else:
    lm='Parsed modes after excluding the six lowest (translation/rotation) modes are non-negative to the -10 cm^-1 reporting threshold; this supports, but does not prove, a local minimum in the harmonic approximation.'
def src(filename, location):
    return {'internal_request_key':res.get('request_key', request_key),'filename':filename,'location':location}
retained=sorted(files.keys())
obs=[]
obs.append({'name':'optimized_geometry','value': geom if geom else {'available':False,'reason':'No job.xyz geometry parsed'},'unit':'angstrom' if geom else None,'sources':[src('job.xyz','final optimized Cartesian coordinates')] if 'job.xyz' in files else [],'formula':None,'artifacts':['observations.json'],'limitations':[] if len(geom)==9 else ['Expected 9 atoms; parsed %d' % len(geom)]})
obs.append({'name':'vibrational_frequencies','value': freq if freq else {'available':False,'reason':'No frequency lines parsed from stdout.out'},'unit':'cm^-1' if freq else None,'sources':[src('stdout.out','ORCA frequency section')] if 'stdout.out' in files else [],'formula':None,'artifacts':['observations.json'],'limitations':[] if len(freq)==27 else ['Expected 27 modes including translations/rotations; parsed %d' % len(freq)]})
obs.append({'name':'local_minimum_assessment','value':{'assessment':lm,'optimization_converged_marker':conv,'n_frequencies':len(freq),'excluded_lowest_six':len(freq)>=27,'imaginary_threshold_cm-1':-10.0},'unit':None,'sources':[src('stdout.out','convergence and frequency sections')] if 'stdout.out' in files else [],'formula':None,'artifacts':['observations.json'],'limitations':['Harmonic approximation; gas phase; no independent validation.']})
obs.append({'name':'artifact_retention','value':{'returned_files':retained,'local_files':['observations.json'],'request_key':res.get('request_key', request_key),'operation_status':res.get('operation_status'),'error':error},'unit':None,'sources':[src(k,'returned by SDK') for k in retained],'formula':None,'artifacts':['observations.json'],'limitations':[]})
qa={'execution':'SDK ORCA request returned operation_status=%s; this is execution information, not a scientific qualification.' % res.get('operation_status'),'scientific_checks':'Parsed job.xyz and stdout.out; checked for an optimization convergence marker and parsed frequency lines. No independent scientific validation was performed.','verification_gaps':['ORCA output was not independently verified','harmonic frequency approximation','gas-phase only','no experimental comparison']}
obs.append({'name':'qa_gap_report','value':qa,'unit':None,'sources':[src('stdout.out','ORCA output')] if 'stdout.out' in files else [],'formula':None,'artifacts':['observations.json'],'limitations':[]})
obs.append({'name':'completion_caveat','value':'A normal program termination is not treated as proof of optimization convergence or a local minimum. Conclusions are limited to parsed ORCA output; unresolved or unparsed items remain gaps.','unit':None,'sources':[src('stdout.out','ORCA output')] if 'stdout.out' in files else [],'formula':None,'artifacts':['observations.json'],'limitations':[]})
seed={'seed':1701,'used':False,'note':'No stochastic structure-generation/search algorithm was used; seed 1701 was recorded for compliance but not consumed.'}
obs.append({'name':'random_seed_record','value':seed,'unit':None,'sources':[],'formula':None,'artifacts':['observations.json'],'limitations':[]})
with open('observations.json','w') as f:
    json.dump({'version':1,'observations':obs}, f, indent=2)

